// Generates src/ui/icons/duotone.generated.ts: only the duotone paths of the Phosphor icons the app uses (owner's choice, 21/10/2026).
// The package ships six weights per icon and a barrel that bundles every icon; importing it cost ~45 KB gz and broke the JS budget.
// Run `npm run icons` after changing the table below; commit the generated file.
import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

/** App icon name → Phosphor icon name. */
const MAP = {
  'menu': 'List', 'x': 'X', 'chevron-down': 'CaretDown', 'chevron-up': 'CaretUp', 'chevron-left': 'CaretLeft',
  'chevron-right': 'CaretRight', 'arrow-right': 'ArrowRight', 'arrow-left': 'ArrowLeft', 'arrow-up-right': 'ArrowUpRight',
  'house': 'House', 'house-heart': 'HouseLine', 'layout-dashboard': 'SquaresFour', 'inbox': 'Tray',
  'calendar-days': 'CalendarDots', 'calendar-check': 'CalendarCheck', 'users-round': 'UsersThree', 'receipt': 'Receipt',
  'tags': 'Tag', 'chart-column': 'ChartBar', 'link-2': 'LinkSimple', 'unlink': 'LinkBreak', 'circle-user-round': 'UserCircle',
  'search': 'MagnifyingGlass', 'plus': 'Plus', 'ellipsis-vertical': 'DotsThreeVertical', 'log-in': 'SignIn',
  'log-out': 'SignOut', 'shield-user': 'IdentificationBadge', 'rotate-ccw': 'ArrowCounterClockwise', 'clock': 'Clock',
  'phone': 'Phone', 'phone-outgoing': 'PhoneOutgoing', 'phone-missed': 'PhoneX', 'circle-x': 'XCircle',
  'circle-minus': 'MinusCircle', 'circle-check': 'CheckCircle', 'check': 'Check', 'eye': 'Eye', 'eye-off': 'EyeSlash',
  'lock': 'Lock', 'send': 'PaperPlaneTilt', 'file-pen': 'NotePencil', 'file-x': 'FileX', 'banknote': 'Money',
  'landmark': 'Bank', 'qr-code': 'QrCode', 'triangle-alert': 'Warning', 'heart': 'Heart', 'door-open': 'DoorOpen',
  'hourglass': 'Hourglass', 'volume-x': 'SpeakerSlash', 'play': 'Play', 'pause': 'Pause', 'maximize': 'ArrowsOut',
  'map-pin': 'MapPin', 'mail': 'Envelope', 'printer': 'Printer', 'copy': 'Copy', 'info': 'Info',
  'message-circle': 'ChatCircle', 'moon': 'Moon', 'utensils': 'ForkKnife', 'smile': 'Smiley', 'footprints': 'Footprints',
  'bone': 'Bone', 'user-round': 'User', 'settings': 'Gear', 'trash-2': 'Trash', 'pencil': 'PencilSimple',
  'calendar-plus': 'CalendarPlus', 'clipboard-list': 'ClipboardText', 'activity': 'Pulse', 'thermometer': 'Thermometer',
  'notebook-pen': 'Notebook', 'video': 'VideoCamera', 'image': 'Image', 'external-link': 'ArrowSquareOut',
  'navigation': 'NavigationArrow', 'refresh-cw': 'ArrowsClockwise', 'filter': 'Funnel', 'list': 'ListBullets',
  'grid-2x2': 'GridFour', 'cake': 'Cake', 'gender-male': 'GenderMale', 'gender-female': 'GenderFemale', 'scales': 'Scales',
  'bell': 'Bell', 'package': 'Package', 'sliders-horizontal': 'SlidersHorizontal', 'lifebuoy': 'Lifebuoy',
};

const defs = (name) => fileURLToPath(new URL(`../node_modules/@phosphor-icons/react/dist/defs/${name}.es.js`, import.meta.url));
const out = {};
for (const [app, ph] of Object.entries(MAP)) {
  const text = readFileSync(defs(ph), 'utf8');
  const from = text.indexOf('"duotone"');
  if (from < 0) throw new Error(`${ph}: no duotone weight`);
  const end = text.indexOf('\n  ],', from);
  const block = text.slice(from, end < 0 ? text.length : end);
  const paths = [...block.matchAll(/createElement\(\s*"(\w+)",\s*\{([^}]*)\}/g)].map(([, tag, attrs]) => {
    if (tag !== 'path') throw new Error(`${ph}: unexpected <${tag}> in the duotone weight`);
    const d = /d:\s*"([^"]+)"/.exec(attrs)?.[1];
    const opacity = /opacity:\s*"([^"]+)"/.exec(attrs)?.[1];
    if (!d) throw new Error(`${ph}: path without d`);
    return opacity ? [d, opacity] : [d];
  });
  if (paths.length === 0) throw new Error(`${ph}: no paths found`);
  out[app] = paths;
}
const body = Object.entries(out).map(([k, v]) => `  '${k}': ${JSON.stringify(v)},`).join('\n');
writeFileSync(
  new URL('../src/ui/icons/duotone.generated.ts', import.meta.url),
  `/* Generated by scripts/duotone-icons.mjs (npm run icons) from @phosphor-icons/react, duotone weight, viewBox 0 0 256 256. Do not edit. */\n`
  + `export const DUOTONE: Record<string, readonly (readonly [d: string, opacity?: string])[]> = {\n${body}\n};\n`,
);
console.log(`wrote ${Object.keys(out).length} icons`);
